// Package semver parses and orders Semantic Versioning 2.0.0 versions.
package semver

import (
	"cmp"
	"fmt"
	"slices"
	"strconv"
	"strings"
)

// Version is a parsed version. Pre and Build hold the dot-separated identifiers.
type Version struct {
	Major, Minor, Patch uint64
	Pre                 []string
	Build               []string
}

// Parse parses s as a SemVer 2.0.0 version.
func Parse(s string) (Version, error) {
	var v Version
	rest, build, hasBuild := strings.Cut(s, "+")
	if hasBuild {
		ids, err := identifiers(build, false)
		if err != nil {
			return Version{}, err
		}
		v.Build = ids
	}
	core, pre, hasPre := strings.Cut(rest, "-")
	if hasPre {
		ids, err := identifiers(pre, true)
		if err != nil {
			return Version{}, err
		}
		v.Pre = ids
	}
	parts := strings.Split(core, ".")
	if len(parts) != 3 {
		return Version{}, fmt.Errorf("semver: %q is not MAJOR.MINOR.PATCH", core)
	}
	for i, field := range []*uint64{&v.Major, &v.Minor, &v.Patch} {
		if !numeric(parts[i]) || leadingZero(parts[i]) {
			return Version{}, fmt.Errorf("semver: invalid number %q", parts[i])
		}
		n, err := strconv.ParseUint(parts[i], 10, 64)
		if err != nil {
			return Version{}, fmt.Errorf("semver: %w", err)
		}
		*field = n
	}
	return v, nil
}

// identifiers splits a prerelease or build section into validated identifiers.
func identifiers(s string, pre bool) ([]string, error) {
	ids := strings.Split(s, ".")
	for _, id := range ids {
		if id == "" || strings.IndexFunc(id, invalid) >= 0 {
			return nil, fmt.Errorf("semver: invalid identifier %q", id)
		}
		if pre && numeric(id) && leadingZero(id) {
			return nil, fmt.Errorf("semver: leading zero in %q", id)
		}
	}
	return ids, nil
}

func invalid(r rune) bool {
	return !(r == '-' || '0' <= r && r <= '9' || 'a' <= r && r <= 'z' || 'A' <= r && r <= 'Z')
}

func numeric(s string) bool {
	return s != "" && strings.Trim(s, "0123456789") == ""
}

func leadingZero(s string) bool {
	return len(s) > 1 && s[0] == '0'
}

// String formats v in SemVer syntax.
func (v Version) String() string {
	s := fmt.Sprintf("%d.%d.%d", v.Major, v.Minor, v.Patch)
	if len(v.Pre) > 0 {
		s += "-" + strings.Join(v.Pre, ".")
	}
	if len(v.Build) > 0 {
		s += "+" + strings.Join(v.Build, ".")
	}
	return s
}

// Compare orders a and b by SemVer precedence: -1, 0 or 1.
func Compare(a, b Version) int {
	if c := cmp.Or(cmp.Compare(a.Major, b.Major), cmp.Compare(a.Minor, b.Minor), cmp.Compare(a.Patch, b.Patch)); c != 0 {
		return c
	}
	// A release ranks above any of its prereleases.
	if len(a.Pre) == 0 || len(b.Pre) == 0 {
		return cmp.Compare(len(b.Pre), len(a.Pre))
	}
	for i := 0; i < len(a.Pre) && i < len(b.Pre); i++ {
		if c := compareIdentifier(a.Pre[i], b.Pre[i]); c != 0 {
			return c
		}
	}
	return cmp.Compare(len(a.Pre), len(b.Pre))
}

func compareIdentifier(x, y string) int {
	switch xn, yn := numeric(x), numeric(y); {
	case xn && yn:
		// Without leading zeros, a longer number is larger.
		return cmp.Or(cmp.Compare(len(x), len(y)), strings.Compare(x, y))
	case xn:
		return -1
	case yn:
		return 1
	}
	return strings.Compare(x, y)
}

// Constraint is a parsed version range.
type Constraint struct {
	alternatives [][]comparator
}

type comparator struct {
	op string
	v  Version
}

var operators = []string{"", "=", "!=", "<", "<=", ">", ">=", "~", "^"}

// ParseConstraint parses a version range such as ">=1.2.3 <2.0.0 || ^3.1.0".
func ParseConstraint(s string) (Constraint, error) {
	var c Constraint
	for _, alternative := range strings.Split(s, "||") {
		fields := strings.Fields(alternative)
		if len(fields) == 0 {
			return Constraint{}, fmt.Errorf("semver: empty alternative in %q", s)
		}
		var all []comparator
		for i := 0; i < len(fields); i++ {
			if i+1 < len(fields) && fields[i+1] == "-" {
				// A hyphen range "A - B" is >=A <=B.
				if i+2 == len(fields) {
					return Constraint{}, fmt.Errorf("semver: hyphen range without an upper bound in %q", s)
				}
				low, err := Parse(fields[i])
				if err != nil {
					return Constraint{}, err
				}
				high, err := Parse(fields[i+2])
				if err != nil {
					return Constraint{}, err
				}
				all = append(all, comparator{">=", low}, comparator{"<=", high})
				i += 2
				continue
			}
			field := fields[i]
			op := field[:len(field)-len(strings.TrimLeft(field, "=!<>~^"))]
			if !slices.Contains(operators, op) {
				return Constraint{}, fmt.Errorf("semver: unknown operator %q", op)
			}
			v, err := Parse(field[len(op):])
			if err != nil {
				return Constraint{}, err
			}
			all = append(all, comparator{cmp.Or(op, "="), v})
		}
		c.alternatives = append(c.alternatives, all)
	}
	return c, nil
}

// Check reports whether v satisfies c.
func (c Constraint) Check(v Version) bool {
	return slices.ContainsFunc(c.alternatives, func(all []comparator) bool { return holdsAll(all, v) })
}

func holdsAll(all []comparator, v Version) bool {
	// A prerelease only matches next to a comparator naming a prerelease of the same core.
	allowed := len(v.Pre) == 0
	for _, c := range all {
		if !c.holds(v) {
			return false
		}
		allowed = allowed || len(c.v.Pre) > 0 && c.v.Major == v.Major && c.v.Minor == v.Minor && c.v.Patch == v.Patch
	}
	return allowed
}

func (c comparator) holds(v Version) bool {
	d := Compare(v, c.v)
	switch c.op {
	case "=":
		return d == 0
	case "!=":
		return d != 0
	case "<":
		return d < 0
	case "<=":
		return d <= 0
	case ">":
		return d > 0
	case ">=":
		return d >= 0
	case "~":
		return d >= 0 && Compare(v, Version{Major: c.v.Major, Minor: c.v.Minor + 1}) < 0
	}
	upper := Version{Major: c.v.Major + 1}
	if c.v.Major == 0 && c.v.Minor == 0 {
		upper = Version{Patch: c.v.Patch + 1}
	} else if c.v.Major == 0 {
		upper = Version{Minor: c.v.Minor + 1}
	}
	return d >= 0 && Compare(v, upper) < 0
}

// Max returns the highest version that satisfies c.
func Max(versions []Version, c Constraint) (Version, bool) {
	var best Version
	found := false
	for _, v := range versions {
		if c.Check(v) && (!found || Compare(v, best) > 0) {
			best, found = v, true
		}
	}
	return best, found
}

// IncMajor returns the next major version.
func (v Version) IncMajor() Version {
	// A prerelease of X.0.0 is released as X.0.0.
	if len(v.Pre) > 0 && v.Minor == 0 && v.Patch == 0 {
		return Version{Major: v.Major}
	}
	return Version{Major: v.Major + 1}
}

// IncMinor returns the next minor version.
func (v Version) IncMinor() Version {
	if len(v.Pre) > 0 && v.Patch == 0 {
		return Version{Major: v.Major, Minor: v.Minor}
	}
	return Version{Major: v.Major, Minor: v.Minor + 1}
}

// IncPatch returns the next patch version.
func (v Version) IncPatch() Version {
	if len(v.Pre) > 0 {
		return Version{Major: v.Major, Minor: v.Minor, Patch: v.Patch}
	}
	return Version{Major: v.Major, Minor: v.Minor, Patch: v.Patch + 1}
}

// Sort orders versions by precedence.
func Sort(versions []Version) {
	slices.SortStableFunc(versions, Compare)
}

