// Package textwrap wraps plain text to a width counted in runes.
package textwrap

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

// Wrap wraps text into lines of at most width runes.
func Wrap(text string, width int) []string {
	return wrap(text, width, "", "", false)
}

// Justify is Wrap with inner lines widened to width.
func Justify(text string, width int) []string {
	return wrap(text, width, "", "", true)
}

// WrapIndent is Wrap with a prefix on each line.
func WrapIndent(text string, width int, first, rest string) []string {
	return wrap(text, width, first, rest, false)
}

// wrap wraps each paragraph; first and rest prefix its lines and count toward width.
func wrap(text string, width int, first, rest string, justified bool) []string {
	width = max(width, 1)
	firstRoom := max(width-utf8.RuneCountInString(first), 1)
	restRoom := max(width-utf8.RuneCountInString(rest), 1)
	var lines []string
	for _, words := range paragraphs(text) {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		paragraph := wrapWords(words, firstRoom, restRoom)
		for i, line := range paragraph {
			prefix, room := rest, restRoom
			if i == 0 {
				prefix, room = first, firstRoom
			}
			if justified && i < len(paragraph)-1 {
				line = justify(line, room)
			}
			lines = append(lines, prefix+line)
		}
	}
	return lines
}

// justify widens line to width runes, giving leftmost gaps the extra spaces.
func justify(line string, width int) string {
	words := strings.Split(line, " ")
	gaps := len(words) - 1
	if gaps == 0 {
		return line
	}
	spaces := width - utf8.RuneCountInString(line) + gaps
	var b strings.Builder
	for i, word := range words {
		b.WriteString(word)
		if i < gaps {
			n := spaces / gaps
			if i < spaces%gaps {
				n++
			}
			b.WriteString(strings.Repeat(" ", n))
		}
	}
	return b.String()
}

// paragraphs returns the words of each paragraph. Blank lines separate paragraphs.
func paragraphs(text string) [][]string {
	var out [][]string
	var words []string
	for _, line := range strings.Split(text, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 && len(words) > 0 {
			out = append(out, words)
			words = nil
		}
		words = append(words, fields...)
	}
	if len(words) > 0 {
		out = append(out, words)
	}
	return out
}

// wrapWords fills lines greedily; the first line holds first runes and later lines rest.
func wrapWords(words []string, first, rest int) []string {
	var lines []string
	room := first
	line, n := "", 0
	for _, word := range words {
		size := utf8.RuneCountInString(word)
		if n > 0 && n+1+size <= room {
			line, n = line+" "+word, n+1+size
			continue
		}
		if n > 0 {
			lines, room = append(lines, line), rest
		}
		// An over-long word starts its own line and is cut into pieces that fill each line.
		for size > room {
			piece, more := cut(word, room)
			word, size = more, size-room
			lines, room = append(lines, piece), rest
		}
		line, n = word, size
	}
	return append(lines, line)
}

// cut splits s after its first n runes.
func cut(s string, n int) (string, string) {
	for i := range s {
		if n == 0 {
			return s[:i], s[i:]
		}
		n--
	}
	return s, ""
}

// Fill is Wrap joined with newlines.
func Fill(text string, width int) string {
	return strings.Join(Wrap(text, width), "\n")
}

// Indent adds prefix to the start of lines of text.
func Indent(text, prefix string) string {
	var b strings.Builder
	for _, line := range strings.SplitAfter(text, "\n") {
		if strings.TrimSpace(line) != "" {
			b.WriteString(prefix)
		}
		b.WriteString(line)
	}
	return b.String()
}

// Dedent removes the common leading whitespace of text's lines.
func Dedent(text string) string {
	lines := strings.SplitAfter(text, "\n")
	margin, found := "", false
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := line[:len(line)-len(strings.TrimLeft(line, " \t"))]
		if !found {
			margin, found = indent, true
		}
		for !strings.HasPrefix(indent, margin) {
			margin = margin[:len(margin)-1]
		}
	}
	var b strings.Builder
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			if strings.HasSuffix(line, "\n") {
				b.WriteByte('\n')
			}
			continue
		}
		b.WriteString(line[len(margin):])
	}
	return b.String()
}

// Shorten fits text on one line of at most width runes.
func Shorten(text string, width int, placeholder string) string {
	words := strings.Fields(text)
	if line := strings.Join(words, " "); utf8.RuneCountInString(line) <= width {
		return line
	}
	size := utf8.RuneCountInString(placeholder)
	kept := 0
	for i, word := range words {
		size += utf8.RuneCountInString(word) + min(i, 1)
		if size > width {
			break
		}
		kept++
	}
	if kept > 0 {
		return strings.Join(words[:kept], " ") + placeholder
	}
	if alone := strings.TrimLeftFunc(placeholder, unicode.IsSpace); utf8.RuneCountInString(alone) <= width {
		return alone
	}
	return ""
}

// ExpandTabs replaces tabs with spaces.
func ExpandTabs(text string, tabSize int) string {
	tabSize = max(tabSize, 1)
	var b strings.Builder
	column := 0
	for _, r := range text {
		switch r {
		case '\t':
			n := tabSize - column%tabSize
			b.WriteString(strings.Repeat(" ", n))
			column += n
		case '\n':
			b.WriteRune(r)
			column = 0
		default:
			b.WriteRune(r)
			column++
		}
	}
	return b.String()
}

// Center pads line with spaces to width runes.
func Center(line string, width int) string {
	pad := max(width-utf8.RuneCountInString(line), 0)
	return strings.Repeat(" ", pad/2) + line + strings.Repeat(" ", pad-pad/2)
}

// Table aligns rows of cells into columns.
func Table(rows [][]string, gap int) []string {
	var widths []int
	for _, row := range rows {
		for i, cell := range row {
			if i == len(widths) {
				widths = append(widths, 0)
			}
			widths[i] = max(widths[i], utf8.RuneCountInString(cell))
		}
	}
	separator := strings.Repeat(" ", max(gap, 1))
	lines := make([]string, 0, len(rows))
	for _, row := range rows {
		var b strings.Builder
		for i, cell := range row {
			if i > 0 {
				b.WriteString(separator)
			}
			b.WriteString(cell + strings.Repeat(" ", widths[i]-utf8.RuneCountInString(cell)))
		}
		lines = append(lines, strings.TrimRight(b.String(), " "))
	}
	return lines
}

// Box wraps text inside a border.
func Box(text string, width int) []string {
	lines := Wrap(text, width-4)
	inner := 0
	for _, line := range lines {
		inner = max(inner, utf8.RuneCountInString(line))
	}
	edge := "+" + strings.Repeat("-", inner+2) + "+"
	box := []string{edge}
	for _, line := range lines {
		box = append(box, "| "+line+strings.Repeat(" ", inner-utf8.RuneCountInString(line))+" |")
	}
	return append(box, edge)
}

