func TestTable(t *testing.T) {
	rows := [][]string{{"name", "qty", "note"}, {"雪", "12"}, {"apple", "3", "ripe"}, {}}
	want := []string{"name   qty  note", "雪      12", "apple  3    ripe", ""}
	if got := textwrap.Table(rows, 2); !slices.Equal(got, want) {
		t.Errorf("Table = %q, want %q", got, want)
	}
	if got := textwrap.Table([][]string{{"a", "b"}, {"cc", ""}}, 0); !slices.Equal(got, []string{"a  b", "cc"}) {
		t.Errorf("Table gap 0 = %q", got)
	}
	if got := textwrap.Table(nil, 1); len(got) != 0 {
		t.Errorf("Table(nil) = %q", got)
	}
}

func TestBox(t *testing.T) {
	want := []string{"+--------+", "| one    |", "| two    |", "| three  |", "|        |", "| fourth |", "+--------+"}
	if got := textwrap.Box("one two three\n\nfourth", 10); !slices.Equal(got, want) {
		t.Errorf("Box = %q, want %q", got, want)
	}
	if got := textwrap.Box("雪 x", 20); !slices.Equal(got, []string{"+-----+", "| 雪 x |", "+-----+"}) {
		t.Errorf("Box runes = %q", got)
	}
	if got := textwrap.Box("ab", 2); !slices.Equal(got, []string{"+---+", "| a |", "| b |", "+---+"}) {
		t.Errorf("Box narrow = %q", got)
	}
	if got := textwrap.Box(" ", 8); !slices.Equal(got, []string{"+--+", "+--+"}) {
		t.Errorf("Box empty = %q", got)
	}
}
